	ret = [0] * (n + 1)

	@bootstrap
	def dfs1(node, par):
		dp[node] = arr[node - 1] if arr[node - 1] == 1 else -1
		for nex in gp[node]:
			if nex == par:
				continue
			yield dfs1(nex, node)
			if dp[nex] > 0:
				dp[node] += dp[nex]
		yield None

	@bootstrap
	def dfs2(node, par):
		ret[node] = dp[node]
